(()=>{'use strict';const key='sb_publishable_KQGD-vWlAlJi_Bv7fSaEvA_YLJpIgyu';const endpoint='https://pzymmsfjgspvzbivzvkx.supabase.co/functions/v1/mowmatter-capture';const prefs=document.getElementById('measurement-form');if(prefs){const box=document.getElementById('measurement-on');try{box.checked=localStorage.getItem('mm-measurement-consent')==='2026-10-07'&&localStorage.getItem('mm-measurement-off')!=='1'}catch{}prefs.onsubmit=e=>{e.preventDefault();const status=document.getElementById('measurement-status');try{localStorage.setItem('mm-measurement-consent',box.checked?'2026-10-07':'');localStorage.setItem('mm-measurement-off',box.checked?'0':'1');status.textContent='Your preference is saved on this browser.'}catch{status.textContent='Browser storage is unavailable. Optional measurement stays off.'}}}const form=document.getElementById('legal-request');if(!form)return;const started=Date.now(),submission=crypto.randomUUID();const requestType=form.elements.request_type;function updateType(){const stop=requestType.value==='unsubscribe',message=form.elements.message,consent=form.elements.contact_consent;message.required=!stop;message.closest('label').hidden=stop;consent.required=!stop;consent.closest('label').hidden=stop;if(stop){message.value='Stop all optional marketing emails.';consent.checked=true}else{message.value='';consent.checked=false}form.querySelector('button').textContent=stop?'Stop marketing emails':'Send request'}requestType.addEventListener('change',updateType);if(new URLSearchParams(location.search).get('request_type')==='unsubscribe')requestType.value='unsubscribe';updateType();form.onsubmit=async e=>{e.preventDefault();if(!form.reportValidity())return;const button=form.querySelector('button'),status=document.getElementById('request-status'),f=new FormData(form);button.disabled=true;status.textContent='Saving your request…';try{const r=await fetch(endpoint,{method:'POST',headers:{apikey:key,'Content-Type':'application/json'},body:JSON.stringify({kind:'compliance_request',submission_id:submission,request_type:f.get('request_type'),email:f.get('email'),message:f.get('message'),contact_consent:f.get('contact_consent')==='on',website:f.get('website'),elapsed_ms:Date.now()-started,notice_version:'2026-10-07'}),signal:AbortSignal.timeout(15000)});const d=await r.json();if(!r.ok||!d.ok)throw Error(d.error||'Could not save your request. Please try again.');status.textContent=f.get('request_type')==='unsubscribe'?'Your marketing opt-out has been recorded. This does not cancel service or stop necessary account notices.':'Your request is saved for review. We may contact you to verify authority before disclosing or deleting information.';status.focus();form.querySelectorAll('input,textarea,select,button').forEach(x=>x.disabled=true)}catch(err){status.textContent=err.name==='TimeoutError'?'The request timed out. Please try again.':err.message;button.disabled=false}}})();